import { field, textarea, select, checkbox, htmlEscape, attrEscape, normalizeUrl } from "../tool-core.js";export default {form: `<div class="field-grid">${textarea({id: "htmlInput",label: "Paste HTML",value: "<h1>Page Title</h1>\n<h2>Section One</h2>\n<h3>Subsection A</h3>\n<h2>Section Two</h2>\n<h4>Problem subsection</h4>",help: "Paste HTML containing heading tags (h1-h6) to analyze."})}</div>`,generate(root) {const html = root.querySelector("#htmlInput").value;const regex = /<h([1-6])[^>]*>(.*?)<\/h\1>/gi;const headings = [];let match;while ((match = regex.exec(html)) !== null) {headings.push({ level: parseInt(match[1], 10), text: match[2].replace(/<[^>]*>/g, "").trim() });}if (headings.length === 0) return { output: "No headings found." };const lines = [];let hasH1 = false;headings.forEach((h, i) => {if (h.level === 1) hasH1 = true;const indent = " ".repeat(h.level - 1);let line = `${indent}H${h.level}: ${h.text}`;if (i > 0) {const prev = headings[i - 1];if (h.level > prev.level + 1) {const skipped = [];for (let l = prev.level + 1; l < h.level; l++) skipped.push(`H${l}`);line = `${indent}H${h.level}: SKIPPED ${skipped.join(", ")} — ${h.text}`;}}lines.push(line);});return { output: (hasH1 ? "" : "MISSING H1\n\n") + lines.join("\n") };}};